    }
    KeyEntity saved = keyRepository.save(
        new KeyEntity(request.getCardId(), request.getKeyVersion(), "ACTIVE"));
    return new KeyIssueResponse(saved.getKeyId().toString(), saved.getStatus());
}

@RestControllerAdvice
public class ApiExceptionHandler {
    @ExceptionHandler(KeyAlreadyExistsException.class)
    public ResponseEntity<ErrorResponse> handleDuplicate(KeyAlreadyExistsException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("E409", e.getMessage()));
    }
}

// POST /api/keys のボディ: {"cardId":"","keyVersion":2}

@Data
public class KeyIssueRequest {
    @NotBlank
    private String cardId;
    @NotNull @Min(1) @Max(255)
    private Integer keyVersion;
}

@PostMapping
public ResponseEntity<KeyIssueResponse> issue(@Valid @RequestBody KeyIssueRequest request) {
    return ResponseEntity.status(HttpStatus.CREATED).body(keyIssueService.issue(request));
}

public interface KeyRepository extends JpaRepository<KeyEntity, Long> {
    boolean existsByCardIdAndStatus(String cardId, String status);
}

// Service の別のメソッド
public KeyEntity findLatest(Long keyId) {
    return keyRepository.findById(keyId)
        .orElseThrow(() -> new KeyNotFoundException(keyId));
}

@Transactional
public KeyIssueResponse issue(KeyIssueRequest request) {
    if (keyRepository.existsByCardIdAndStatus(request.getCardId(), "ACTIVE")) {
        throw new KeyAlreadyExistsException(request.getCardId());
    }
    KeyEntity saved = keyRepository.save(
        new KeyEntity(request.getCardId(), request.getKeyVersion(), "ACTIVE"));
    notifyAsync(saved);  // 別スレッドで通知を送るだけの、@Transactional の付いていないメソッド
    return new KeyIssueResponse(saved.getKeyId().toString(), saved.getStatus());
}
